function drawTextIcons(root){
  const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT),nodes=[];
  while(walker.nextNode()){
    const node=walker.currentNode;
    if(/[→↗←⌄↶]/.test(node.data)&&node.parentElement?.closest('button,summary,.lesson-status,.module-arrow,.tile-arrow,.feature-card em')&&!node.parentElement?.closest('pre,code,[data-highlight-block]'))nodes.push(node);
  }
  for(const node of nodes){
    const parts=node.data.split(/([→↗←⌄↶])/),fragment=document.createDocumentFragment();
    for(const part of parts){if(symbolIcons[part]){const icon=document.createElement('span');icon.className='drawn-arrow';icon.innerHTML=symbolIcons[part];fragment.append(icon)}else if(part)fragment.append(document.createTextNode(part))}
    node.replaceWith(fragment);
  }
}
