  const extra=context==='flashcards'?`<button class="module-card all-deck" data-open-deck="0"><span class="module-index">ALL MODULES</span><strong>Complete term deck</strong><small>${deck.length} definitions · ${masteredCount()} mastered</small>${progressBar(masteredCount(),deck.length)}</button>${state.course==='networking'?`<button class="module-card all-deck" data-open-conversions="1"><span class="module-index">NUMBER PRACTICE</span><strong>Binary and hexadecimal conversions</strong><small>${networkingConversionCards.length} problems · ${conversionMastered()} mastered</small>${progressBar(conversionMastered(),networkingConversionCards.length,'lavender')}</button>`:''}`:'';
  const content=`${sectionHeader(context==='progress'?'PROGRESS':context==='flashcards'?'FLASHCARDS':'COURSE',title,desc,back)}${context==='progress'?`<div class="progress-summary"><div><span class="eyebrow">LESSONS</span><strong>${reviewedCount()} / ${lessonCount()}</strong>${progressBar(reviewedCount(),lessonCount())}</div><div><span class="eyebrow">FLASHCARDS</span><strong>${masteredCount()+(state.course==='networking'?conversionMastered():0)} / ${deck.length+(state.course==='networking'?networkingConversionCards.length:0)}</strong>${progressBar(masteredCount()+(state.course==='networking'?conversionMastered():0),deck.length+(state.course==='networking'?networkingConversionCards.length:0),'lavender')}</div><div><span class="eyebrow">MOCK EXAMS</span><strong>${sets.filter(s=>scoreRecord(s.id).attempts>0).length} / ${sets.length}</strong>${progressBar(sets.filter(s=>scoreRecord(s.id).attempts>0).length,sets.length,'peach')}</div></div>`:''}<div class="module-grid">${extra}${course.modules.map(m=>{const done=m.topics.filter((_,i)=>saved.reviewed.includes(topicKey(m.id,i))).length;const known=masteredCount(m.id),cards=moduleCards(m.id);return `<button class="module-card" ${context==='flashcards'?`data-open-deck="${m.id}"`:`data-open-module="${m.id}"`}><span class="module-index">MODULE ${String(m.id).padStart(2,'0')}</span><strong>${esc(m.title)}</strong><small>${context==='flashcards'?`${cards.length} definitions · ${known} mastered`:`${m.topics.length} lessons · ${done} reviewed`}</small>${progressBar(context==='flashcards'?known:done,context==='flashcards'?cards.length:m.topics.length,context==='flashcards'?'lavender':'sage')}<span class="module-arrow">→</span></button>`}).join('')}</div>${context==='progress'?`<div class="exam-progress"><h2>Mock exam progress</h2>${sets.map(s=>{const r=scoreRecord(s.id);return `<div class="exam-progress-row"><span>${esc(s.title)}</span><strong>${r.best==null?'Not started':`Best ${r.best}/100`}</strong></div>`}).join('')}</div>`:''}`
