function saveSelectedHighlight(){if(state.screen!=='lesson'||!state.highlightMode)return;const mark=captureHighlight();if(!mark)return;cancelTouchHighlight();saved.highlights[mark.id]=saved.highlights[mark.id]||[];saved.highlights[mark.id].push([mark.start,mark.end,saved.highlightColor]);saved.highlightHistory.push(mark.id);state.highlightNotice='Highlight saved.';window.getSelection?.()?.removeAllRanges();persist();render()}
function undoHighlight(){cancelTouchHighlight();for(let i=saved.highlightHistory.length-1;i>=0;i--){const id=saved.highlightHistory[i];if(!id.startsWith(lessonPrefix())||!saved.highlights[id]?.length)continue;saved.highlightHistory.splice(i,1);saved.highlights[id].pop();if(!saved.highlights[id].length)delete saved.highlights[id];state.highlightNotice='Last highlight undone.';persist();render();return}}
