function baseFlashCards(){return state.deckType==='conversion'?networkingConversionCards:moduleCards(state.deckModule)}
function flashCards(){const deck=baseFlashCards(),keys=state.flashSession?.cardKeys,limited=keys?deck.filter(card=>keys.includes(cardKey(card))):deck,order=state.flashSession?.cardOrder;if(!order)return limited;const lookup=new Map(limited.map(card=>[cardKey(card),card]));return order.map(key=>lookup.get(key)).filter(Boolean)}
function currentCard(){const deck=flashCards();return deck[Math.min(state.cardIndex,deck.length-1)]}
function flashRecordsForDeck(){return saved.flashRecords.filter(r=>r.course===state.course&&r.deckType===state.deckType&&r.deckModule===state.deckModule)}
function shuffledKeys(keys){const result=[...keys];for(let i=result.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[result[i],result[j]]=[result[j],result[i]]}return result}
function startFlashSession(cardKeys=null,shuffled=false){const base=baseFlashCards(),available=cardKeys?base.filter(card=>cardKeys.includes(cardKey(card))):base;state.flashSession={course:state.course,deckType:state.deckType,deckModule:state.deckModule,mode:state.flashMode,orientation:state.orientation,cardKeys:cardKeys&&available.length?available.map(cardKey):null,cardOrder:shuffled?shuffledKeys(available.map(cardKey)):null,shuffled,answers:{}};state.cardIndex=0;state.flipped=false;state.flashFeedback=null;state.flashResult=null}
function toggleFlashShuffle(){
  if(!state.flashSession)startFlashSession();
  const session=state.flashSession,deck=flashCards(),prefix=deck.slice(0,state.cardIndex+1).map(cardKey);
  if(session.shuffled){
    const seen=new Set(prefix),original=baseFlashCards().filter(card=>!session.cardKeys||session.cardKeys.includes(cardKey(card))).map(cardKey);
    session.cardOrder=[...prefix,...original.filter(key=>!seen.has(key))];
    session.shuffled=false;
  }else{
    session.cardOrder=[...prefix,...shuffledKeys(deck.slice(state.cardIndex+1).map(cardKey))];
    session.shuffled=true;
  }
  render();
}
function recordFlashAnswer(card,correct,answer){if(!state.flashSession)startFlashSession();const key=cardKey(card);state.flashSession.answers[key]={correct,answer};if(correct)markMastered(card);else saved.mastered=saved.mastered.filter(item=>item!==key);persist()}
function finishFlash(){const deck=flashCards(),answers=state.flashSession?.answers||{},missed=deck.filter(card=>!answers[cardKey(card)]?.correct).map(card=>({key:cardKey(card),term:card.term,definition:card.definition,answer:answers[cardKey(card)]?.answer||'Not answered'}));const record={id:`${Date.now()}-${Math.random().toString(36).slice(2,8)}`,at:Date.now(),course:state.course,deckType:state.deckType,deckModule:state.deckModule,mode:state.flashSession?.mode||state.flashMode,orientation:state.flashSession?.orientation||state.orientation,shuffled:!!state.flashSession?.shuffled,total:deck.length,correct:deck.length-missed.length,missed};saved.flashRecords=[record,...saved.flashRecords];persist();state.flashResult=record;state.flashSession=null;state.screen='flash-result';render();window.scrollTo(0,0)}
function openFlashRecord(id){const record=saved.flashRecords.find(r=>r.id===id);if(!record)return;state.course=record.course;state.deckType=record.deckType;state.deckModule=record.deckModule;state.flashResult=record;state.flashSession=null;state.screen='flash-result';render();window.scrollTo(0,0)}
function retryFlash(mistakesOnly){const record=state.flashResult;if(!record)return;state.course=record.course;state.deckType=record.deckType;state.deckModule=record.deckModule;state.flashMode=record.mode==='mixed'?'type':record.mode;state.orientation=record.orientation==='term'?'term':'definition';startFlashSession(mistakesOnly?record.missed.map(item=>item.key):null,record.shuffled);state.screen='flash-study';render();window.scrollTo(0,0)}
function flashHistory(){const history=flashRecordsForDeck().slice(0,5);return history.length?`<section class="flash-history"><h2>PAST ATTEMPTS</h2><div>${history.map(r=>`<button type="button" data-open-flash-record="${esc(r.id)}"><span>${new Date(r.at).toLocaleDateString()} · ${esc(r.mode==='mixed'?'Mixed practice':r.mode==='choice'?'Multiple choice':r.mode==='type'?(r.deckType==='conversion'?'Type the answer':'Type the term'):'Flip')}</span><strong>${r.correct}/${r.total}</strong><span>Review →</span></button>`).join('')}</div></section>`:''}
function flashProgressHistory(){const history=saved.flashRecords.filter(r=>r.course===state.course).slice(0,10);return `<section class="flash-history"><h2>FLASHCARD ATTEMPTS</h2>${history.length?`<div>${history.map(r=>`<button type="button" data-open-flash-record="${esc(r.id)}"><span>${new Date(r.at).toLocaleDateString()} · ${r.deckType==='conversion'?'Conversions':r.deckModule?`Module ${r.deckModule}`:'All modules'} · ${esc(r.mode==='mixed'?'Mixed practice':r.mode==='choice'?'Multiple choice':r.mode==='type'?'Typing':'Flip')}</span><strong>${r.correct}/${r.total}</strong><span>Review →</span></button>`).join('')}</div>`:'<p class="subtle-note">Finished flashcard rounds will appear here.</p>'}</section>`}
function mcChoices(card){const others=baseFlashCards().filter(c=>c.term!==card.term&&c.term!==undefined&&(state.deckType==='conversion'||c.module===card.module));const unique=[...new Map(others.map(c=>[c.term,c])).values()];const offset=(state.cardIndex*7+card.module*3)%Math.max(1,unique.length);const distractors=[...unique.slice(offset),...unique.slice(0,offset)].slice(0,3);const options=[card,...distractors];const shift=(state.cardIndex+card.module)%options.length;return [...options.slice(shift),...options.slice(0,shift)]}
function flashStudy(){
  const deck=flashCards(),card=currentCard(),known=state.deckType==='conversion'?conversionMastered():masteredCount(state.deckModule),front=state.orientation==='definition'?card.definition:card.term,back=state.orientation==='definition'?card.term:card.definition,number=state.cardIndex+1,answered=Object.keys(state.flashSession?.answers||{}).length,grade=state.flashSession?.answers[cardKey(card)],last=number===deck.length||answered===deck.length;
  const previous=`<button class="button ghost" data-card-step="-1" ${number===1?'disabled':''}>← Previous</button>`;
  const next=last?'<button class="button solid finish-flash" data-finish-flash="1">Finish & see results</button>':`<button class="button solid" data-card-step="1">Next ${state.deckType==='conversion'?'problem':'definition'} →</button>`;
  const flipCard=`<button class="term-card ${state.flipped?'show-back':''}" data-flip="1" aria-label="Flip card"><span class="term-card-label">${state.flipped?(state.orientation==='definition'?(state.deckType==='conversion'?'ANSWER':'TERM'):(state.deckType==='conversion'?'PROBLEM':'DEFINITION')):(state.orientation==='definition'?(state.deckType==='conversion'?'PROBLEM':'DEFINITION'):(state.deckType==='conversion'?'ANSWER':'TERM'))} · MODULE ${card.module}</span><strong>${esc(state.flipped?back:front)}</strong><small>Click to flip ↗</small></button><div class="flash-self-grade">${state.flipped?`<span>Did you know it?</span><button class="button ${grade&&!grade.correct?'selected-review':'ghost'}" data-card-grade="review">Study again</button><button class="button ${grade?.correct?'selected-knew':'soft'}" data-card-grade="knew">I knew it</button>`:'<span>Flip the card, then check yourself.</span>'}</div><div class="flash-control-row">${previous}${next}</div>`;
  const typed=`<div class="practice-card"><span class="term-card-label">${state.deckType==='conversion'?'PROBLEM':'DEFINITION'} · MODULE ${card.module}</span><h2>${esc(card.definition)}</h2><form id="type-form" class="type-form"><label for="term-answer">${state.deckType==='conversion'?'Type the answer':'Type the term'}</label><div><input id="term-answer" autocomplete="off" spellcheck="false" placeholder="${state.deckType==='conversion'?'Enter the answer':'What is this term?'}" ${state.flashFeedback?'disabled':''}><button class="button solid" ${state.flashFeedback?'disabled':''}>Check</button></div></form>${state.flashFeedback?`<div class="practice-feedback ${state.flashFeedback.correct?'correct':'incorrect'}"><strong>${state.flashFeedback.correct?'That’s right!':(state.deckType==='conversion'?'The answer is ':'The term is ')+esc(card.term)}</strong><p>${state.flashFeedback.correct?'You remembered this definition.':'Review the pair, then try the next card.'}</p></div>`:''}</div><div class="flash-control-row">${previous}${next}</div>`;
  const choice=`<div class="practice-card"><span class="term-card-label">${state.deckType==='conversion'?'PROBLEM':'DEFINITION'} · MODULE ${card.module}</span><h2>${esc(card.definition)}</h2><p class="choice-prompt">${state.deckType==='conversion'?'Which answer matches?':'Which term matches?'}</p><div class="choice-grid">${mcChoices(card).map((option,i)=>`<button class="choice-option ${state.flashFeedback?(option.term===card.term?'correct':state.flashFeedback.choice===option.term?'incorrect':''):''}" data-card-choice="${esc(option.term)}" ${state.flashFeedback?'disabled':''}><span>${'ABCD'[i]}</span>${esc(option.term)}</button>`).join('')}</div>${state.flashFeedback?`<div class="practice-feedback ${state.flashFeedback.correct?'correct':'incorrect'}"><strong>${state.flashFeedback.correct?'Correct!':`${state.deckType==='conversion'?'The answer':'The term'} is ${esc(card.term)}.`}</strong><p>${state.flashFeedback.correct?'This card is marked learned.':'Read the definition once more before moving on.'}</p></div>`:''}</div><div class="flash-control-row">${previous}${next}</div>`;
  return `${sectionHeader('FLASHCARDS',state.deckType==='conversion'?'Binary and hexadecimal conversions':state.deckModule?`Module ${state.deckModule} terms`:'All module terms',`${number} of ${deck.length} · ${answered} answered · ${known} learned`,'flash-modules')}<div class="flash-toolbar"><div class="segmented" aria-label="Practice mode"><button class="${state.flashMode==='flip'?'active':''}" data-flash-mode="flip">Flip</button><button class="${state.flashMode==='type'?'active':''}" data-flash-mode="type">${state.deckType==='conversion'?'Type the answer':'Type the term'}</button><button class="${state.flashMode==='choice'?'active':''}" data-flash-mode="choice">Multiple choice</button></div><button class="shuffle-flash ${state.flashSession?.shuffled?'active':''}" type="button" data-shuffle-flash="1" aria-pressed="${!!state.flashSession?.shuffled}" aria-label="${state.flashSession?.shuffled?'Return to original card order':'Shuffle flashcards'}"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 7h3c4 0 5 10 10 10h5m-4-4 4 4-4 4M3 17h3c2 0 3-2 4-4m3-3c1-2 2-3 3-3h5m-4-4 4 4-4 4" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg><span>${state.flashSession?.shuffled?'Original order':'Shuffle'}</span></button>${state.flashMode==='flip'?`<div class="orientation"><span>Front side</span><button class="${state.orientation==='definition'?'active':''}" data-orientation="definition">${state.deckType==='conversion'?'Problem':'Definition'}</button><button class="${state.orientation==='term'?'active':''}" data-orientation="term">${state.deckType==='conversion'?'Answer':'Term'}</button></div>`:''}</div><div class="flash-progress"><span>${number} / ${deck.length}</span>${progressBar(number,deck.length,'lavender')}<span>${answered} answered</span></div>${state.flashMode==='flip'?flipCard:state.flashMode==='type'?typed:choice}<p class="subtle-note">${state.deckType==='conversion'?'Solve a conversion, then reveal the answer.':'Flashcards contain terms and definitions only.'} Unanswered cards count as needs review. Completed results are saved on this device.</p>${flashHistory()}`
}
function flashResultPage(){const r=state.flashResult;if(!r)return sectionHeader('FLASHCARDS','No result yet','','flash-modules');const percent=r.total?Math.round(r.correct/r.total*100):0,confetti=Array.from({length:28},(_,i)=>`<i style="--x:${(i*37)%100}%;--d:${(i*7)%13/10}s;--r:${(i*53)%360}deg;--c:${['#e8a2b7','#91cce6','#f2d47b','#a8cba7','#c7aed7'][i%5]}"></i>`).join('');return `<section class="flash-result-hero"><div class="flash-confetti" aria-hidden="true">${confetti}</div><div class="flash-result-copy"><span class="eyebrow">FLASHCARDS COMPLETE</span><h1>CONGRATULATIONS!</h1><p>You finished ${r.total} cards. Keep going at your own pace.</p></div><div class="flash-result-score"><strong>${percent}%</strong><span>${r.correct} of ${r.total} remembered</span></div></section><div class="flash-result-summary"><div><strong>${r.correct}</strong><span>Remembered</span></div><div><strong>${r.missed.length}</strong><span>Needs review</span></div><div><strong>${flashRecordsForDeck().length}</strong><span>Completed attempts</span></div></div><div class="flash-result-actions"><button class="button ghost" data-go="flash-modules">← All decks</button>${r.missed.length?'<button class="button soft" data-retry-flash="mistakes">Retake mistakes</button>':''}<button class="button solid" data-retry-flash="whole">Retake whole deck →</button></div><section class="flash-mistakes"><h2>CARDS TO REVIEW</h2>${r.missed.length?r.missed.map((item,i)=>`<article class="flash-mistake"><span>${r.deckType==='conversion'?'PROBLEM':r.mode==='flip'&&r.orientation==='term'?'TERM':'DEFINITION'} ${i+1}</span><h3>${esc(r.mode==='flip'&&r.orientation==='term'?item.term:item.definition)}</h3><p>Your ${r.mode==='flip'?'check':'answer'}: <strong>${esc(item.answer)}</strong></p><p>Correct ${r.deckType==='conversion'?'answer':r.mode==='flip'&&r.orientation==='term'?'definition':'term'}: <strong>${esc(r.mode==='flip'&&r.orientation==='term'?item.definition:item.term)}</strong></p></article>`).join(''):'<p class="flash-all-correct">Lovely work! Every card was marked as remembered.</p>'}</section>${flashHistory()}`}
function examList(){if(!['oop','networking'].includes(state.course))return customEmpty('exam-courses');const sets=activeExamSets();return `${sectionHeader(state.course==='networking'?'NETWORKING 1':'OBJECT-ORIENTED PROGRAMMING','Mock exams',state.course==='networking'?'Two shorter exams based on your Wayground reference and uploaded modules.':'Two 100-point exams based on the uploaded summative assessment topics.','exam-courses')}<div class="exam-grid">${sets.map(s=>{const q=examQuestions(s),draft=saved.examDrafts[s.id],record=scoreRecord(s.id),answered=draft?Object.keys(draft.answers||{}).length:0,points=100/q.length;return `<article class="exam-tile"><span class="exam-emblem">${s===sets[0]?uiIcons.flower:uiIcons.spark}</span><span class="eyebrow">PRACTICE EXAM</span><h2>${esc(s.title)}</h2><p>${q.length} questions · ${points} ${points===1?'point':'points'} each · 100 points total</p><div class="exam-tags"><span>${esc(s.subtitle)}</span><span>${record.best==null?'Not attempted':`Best ${record.best}/100`}</span></div>${draft?`<p class="draft-note">Saved draft · ${answered}/${q.length} answered</p>`:''}<button class="button solid" data-start-exam="${s.id}">${draft?'Resume exam →':'Start exam →'}</button></article>`}).join('')}</div><div class="info-strip">Your answers save as you go. You can leave, switch sections, or close the page and resume later.</div>`}

function examQuestions(set){return set.course==='networking'?networkingExamQuestions.filter(q=>set.modules.includes(q.module)):allExamQuestions.filter(q=>set.summatives.includes(q.summative))}

function mixChoices(q){const options=q.choices.map((text,i)=>({text,correct:i===q.correct}));let seed=(q.id*9301+49297)%233280;for(let i=options.length-1;i>0;i--){seed=(seed*9301+49297)%233280;const j=seed%(i+1);[options[i],options[j]]=[options[j],options[i]]}return options}
function activeQuestions(){return examQuestions(state.exam.set).map(q=>({...q,displayChoices:mixChoices(q)}))}
function saveExamDraft(){if(!state.exam)return;saved.examDrafts[state.exam.set.id]={answers:state.exam.answers,index:state.exam.index};persist()}
function startExam(id){const set=[...examSets,...networkingExamSets].find(s=>s.id===id),draft=saved.examDrafts[id];state.exam={set,answers:{...(draft?.answers||{})},index:Math.min(draft?.index||0,examQuestions(set).length-1)};state.result=null;state.screen='exam-active';saveExamDraft();render();window.scrollTo(0,0)}
function examActive(){const e=state.exam,questions=activeQuestions(),q=questions[e.index],answered=Object.keys(e.answers).length,a=e.answers[q.id];return `<div class="exam-work-top"><button class="back-link" data-go="exam-list">← Exam list</button><span>${esc(e.set.title)} · ${answered}/${questions.length} answered</span></div>${progressBar(answered,questions.length,'peach')}<article class="exam-question"><span class="eyebrow">QUESTION ${e.index+1} OF ${questions.length} · ${e.set.course==='networking'?`MODULE ${q.module}`:`SUMMATIVE ${q.summative}`} · ${100/questions.length} ${100/questions.length===1?'POINT':'POINTS'}</span><h1>${esc(q.prompt)}</h1><div class="answer-list">${q.displayChoices.map((option,i)=>`<label class="answer-option"><input name="exam-answer" type="radio" value="${i}" ${a===i?'checked':''}><span class="answer-letter">${'ABCD'[i]}</span><span>${esc(option.text)}</span></label>`).join('')}</div></article><div class="exam-navigation"><div class="question-dots">${questions.map((item,i)=>`<button class="question-dot ${e.answers[item.id]!=null?'answered':''} ${i===e.index?'current':''}" data-jump-question="${i}" aria-label="Question ${i+1}${e.answers[item.id]!=null?', answered':''}" title="Question ${i+1}"></button>`).join('')}</div><div class="exam-buttons"><button class="button ghost" data-exam-step="-1" ${e.index===0?'disabled':''}>← Previous</button>${e.index===questions.length-1?'<button class="button solid" data-submit-exam="1">Submit exam</button>':'<button class="button solid" data-exam-step="1">Next →</button>'}</div></div><p class="subtle-note">Your selection is saved automatically. Unanswered questions earn zero points.</p>`}
function submitExam(){const e=state.exam,questions=activeQuestions(),missing=questions.filter(q=>e.answers[q.id]==null).length;if(missing&&!window.confirm(`${missing} questions are unanswered. Submit anyway?`))return;let points=0;for(const q of questions){const a=e.answers[q.id];if(a!=null&&q.displayChoices[a]?.correct)points+=100/questions.length}const old=scoreRecord(e.set.id);saved.scores[e.set.id]={best:Math.max(old.best??0,points),last:points,attempts:old.attempts+1};delete saved.examDrafts[e.set.id];persist();state.result={set:e.set,questions,answers:{...e.answers},points};state.exam=null;state.screen='exam-result';render();window.scrollTo(0,0)}
function examResult(){const r=state.result;return `<div class="result-hero"><div><span class="eyebrow">EXAM COMPLETE</span><h1>${esc(r.set.title)}</h1><p>Review each answer to see the idea behind it.</p></div><strong>${r.points}<small>/100</small></strong></div><div class="result-actions"><button class="button ghost" data-go="exam-list">← All exams</button><button class="button solid" data-start-exam="${r.set.id}">Try again ↗</button></div><h2 class="result-heading">Answer review</h2>${r.questions.map((q,i)=>{const a=r.answers[q.id],right=a!=null&&q.displayChoices[a]?.correct,correct=q.displayChoices.find(x=>x.correct)?.text;return `<article class="result-row ${right?'correct':'incorrect'}"><span>QUESTION ${i+1} · ${right?'CORRECT':'REVIEW'}</span><h3>${esc(q.prompt)}</h3><p>Your answer: ${a==null?'Not answered':esc(q.displayChoices[a].text)}</p>${right?'':`<p>Correct answer: <strong>${esc(correct)}</strong></p>`}<div>${esc(q.explanation)}</div></article>`}).join('')}`}
function progressPage(){return coursePicker('progress')}
function render(){navRender();topRender();let content;switch(state.screen){case'dashboard':content=dashboard();break;case'courses':content=coursePicker('courses');break;case'modules':content=moduleGrid('courses');break;case'lessons':content=lessonsPage();break;case'lesson':content=lessonPage();break;case'flash-courses':content=coursePicker('flashcards');break;case'flash-modules':content=moduleGrid('flashcards');break;case'flash-study':content=flashStudy();break;case'flash-result':content=flashResultPage();break;case'exam-courses':content=coursePicker('exams');break;case'exam-list':content=examList();break;case'exam-active':content=examActive();break;case'exam-result':content=examResult();break;case'progress':content=progressPage();break;case'progress-course':content=moduleGrid('progress');break;default:content=dashboard()}page(content,state.screen)}
function go(screen){if(state.screen==='exam-active')saveExamDraft();cancelTouchHighlight();state.screen=screen;state.highlightNotice='';state.pendingHighlight=null;if(screen==='exam-list')state.result=null;render();window.scrollTo(0,0)}
function toggleSidebar(open=!sidebarOpen){sidebarOpen=open;topRender();if(open)document.getElementById('sidebar-close').focus();else document.getElementById('sidebar-toggle').focus()}
function markMastered(card){const key=cardKey(card);if(!saved.mastered.includes(key))saved.mastered.push(key);persist()}
function cardStep(delta){const deck=flashCards();state.cardIndex=Math.max(0,Math.min(deck.length-1,state.cardIndex+delta));state.flipped=false;state.flashFeedback=null;render()}
main.addEventListener('click',event=>{const b=event.target.closest('button');if(!b)return;const d=b.dataset;if(d.go){go(d.go);return}if(d.openCourse){state.course=d.openCourse;go(d.context==='flashcards'?'flash-modules':d.context==='exams'?'exam-list':d.context==='progress'?'progress-course':'modules');return}if(d.openModule){state.module=Number(d.openModule);go('lessons');return}if(d.openLesson!=null){state.lesson=Number(d.openLesson);go('lesson');return}if(d.stepLesson){state.lesson+=Number(d.stepLesson);render();window.scrollTo(0,0);return}if(d.reviewed){saved.reviewed=saved.reviewed.includes(d.reviewed)?saved.reviewed.filter(x=>x!==d.reviewed):[...saved.reviewed,d.reviewed];persist();render();return}if(d.openConversions){state.deckType='conversion';state.deckModule=0;state.cardIndex=0;state.flipped=false;state.flashFeedback=null;state.orientation='definition';startFlashSession();go('flash-study');return}if(d.openDeck!=null){state.deckType='terms';state.deckModule=Number(d.openDeck);state.cardIndex=0;state.flipped=false;state.flashFeedback=null;state.orientation='definition';startFlashSession();go('flash-study');return}if(d.shuffleFlash){toggleFlashShuffle();return}if(d.flashMode){if(state.flashMode!==d.flashMode&&state.flashSession&&Object.keys(state.flashSession.answers).length)state.flashSession.mode='mixed';state.flashMode=d.flashMode;state.flipped=false;state.flashFeedback=null;render();return}if(d.orientation){if(state.orientation!==d.orientation&&state.flashSession&&Object.keys(state.flashSession.answers).length)state.flashSession.orientation='mixed';state.orientation=d.orientation;state.flipped=false;render();return}if(d.flip){state.flipped=!state.flipped;render();return}if(d.cardStep){cardStep(Number(d.cardStep));return}if(d.cardGrade){const c=currentCard(),correct=d.cardGrade==='knew',key=cardKey(c);saved.cardStats[key]=saved.cardStats[key]||{attempts:0,correct:0};saved.cardStats[key].attempts++;if(correct)saved.cardStats[key].correct++;recordFlashAnswer(c,correct,correct?'I knew it':'Study again');state.flashFeedback={correct};render();return}if(d.cardChoice){const c=currentCard(),correct=d.cardChoice===c.term,key=cardKey(c);saved.cardStats[key]=saved.cardStats[key]||{attempts:0,correct:0};saved.cardStats[key].attempts++;if(correct)saved.cardStats[key].correct++;recordFlashAnswer(c,correct,d.cardChoice);state.flashFeedback={correct,choice:d.cardChoice};render();return}if(d.finishFlash){finishFlash();return}if(d.retryFlash){retryFlash(d.retryFlash==='mistakes');return}if(d.openFlashRecord){openFlashRecord(d.openFlashRecord);return}if(d.startExam){startExam(d.startExam);return}if(d.jumpQuestion!=null){state.exam.index=Number(d.jumpQuestion);saveExamDraft();render();return}if(d.examStep){state.exam.index=Math.max(0,Math.min(activeQuestions().length-1,state.exam.index+Number(d.examStep)));saveExamDraft();render();return}if(d.submitExam){submitExam();return}});
main.addEventListener('mouseup',()=>{if(!isTouchDevice()&&Date.now()-lastTouchTime>3000)saveSelectedHighlight()});
main.addEventListener('keyup',saveSelectedHighlight);
main.addEventListener('touchstart',()=>{touchSelecting=true;lastTouchTime=Date.now();cancelTouchHighlight()});
main.addEventListener('touchend',()=>{touchSelecting=false;lastTouchTime=Date.now();scheduleTouchHighlight()});
main.addEventListener('touchcancel',()=>{touchSelecting=false;cancelTouchHighlight()});
document.addEventListener('selectionchange',()=>{if(isTouchDevice())scheduleTouchHighlight()});
main.addEventListener('click',event=>{const button=event.target.closest('button');if(!button)return;if(button.dataset.toggleAnnotations){state.annotationOpen=!state.annotationOpen;render();return}if(button.dataset.addAnnotation){addAnnotation();return}if(button.dataset.deleteAnnotation){deleteAnnotation(button.dataset.deleteAnnotation);return}if(button.dataset.editCourse){showCourseEditor(button.dataset.editCourse);return}if(button.dataset.deleteCourse){showCourseDelete(button.dataset.deleteCourse);return}if(button.dataset.addCourse){document.getElementById('course-dialog').showModal();return}if(button.dataset.highlightColor){const color=button.dataset.highlightColor;if(!['yellow','blue','pink'].includes(color))return;saved.highlightColor=color;state.highlightMode=true;state.highlightNotice=`${color==='pink'?'Baby pink':color==='blue'?'Pastel blue':'Pastel yellow'} highlighter on.`;persist();render();return}if(button.dataset.toggleHighlight){state.highlightMode=!state.highlightMode;if(!state.highlightMode)cancelTouchHighlight();state.highlightNotice=state.highlightMode?'Highlighter on. Select text in a note to save it.':'Highlighter off.';render();return}if(button.dataset.undoHighlight){undoHighlight();return}if(button.dataset.clearHighlights){cancelTouchHighlight();for(const key of Object.keys(saved.highlights))if(key.startsWith(lessonPrefix()))delete saved.highlights[key];saved.highlightHistory=saved.highlightHistory.filter(id=>!id.startsWith(lessonPrefix()));state.highlightNotice='Highlights cleared from this lesson.';persist();render()}});
main.addEventListener('input',event=>{const id=event.target.dataset.annotationId;if(!id)return;const note=lessonAnnotations().find(n=>n.id===id);if(!note)return;note.text=event.target.value;const status=event.target.closest('.annotation-card')?.querySelector('small');if(status)status.textContent=persist()?'Saved on this device':'Could not save on this device';else persist()});
main.addEventListener('change',event=>{if(event.target.name==='exam-answer'&&state.exam){const q=activeQuestions()[state.exam.index];state.exam.answers[q.id]=Number(event.target.value);saveExamDraft();render()}});
main.addEventListener('submit',event=>{if(event.target.id!=='type-form')return;event.preventDefault();const c=currentCard(),input=event.target.querySelector('input'),answer=input.value.trim(),normalize=s=>s.toLocaleLowerCase().replace(/[^a-z0-9]+/g,' ').trim(),correct=normalize(answer)===normalize(c.term),key=cardKey(c);saved.cardStats[key]=saved.cardStats[key]||{attempts:0,correct:0};saved.cardStats[key].attempts++;if(correct)saved.cardStats[key].correct++;recordFlashAnswer(c,correct,answer);state.flashFeedback={correct};render()});
nav.addEventListener('click',event=>{const edit=event.target.closest('[data-edit-course]');if(edit){showCourseEditor(edit.dataset.editCourse);return}const remove=event.target.closest('[data-delete-course]');if(remove){showCourseDelete(remove.dataset.deleteCourse);return}const b=event.target.closest('[data-open-course]');if(!b)return;state.course=b.dataset.openCourse;if(window.matchMedia?.('(max-width:780px)').matches)toggleSidebar(false);go('modules')});
document.getElementById('primary-nav').addEventListener('click',event=>{const b=event.target.closest('[data-go]');if(b)go(b.dataset.go)});
document.querySelector('.brand').addEventListener('click',()=>go('dashboard'));
document.getElementById('sidebar-toggle').addEventListener('click',()=>toggleSidebar());
document.getElementById('sidebar-close').addEventListener('click',()=>toggleSidebar(false));
document.getElementById('sidebar-backdrop').addEventListener('click',()=>toggleSidebar(false));
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&sidebarOpen)toggleSidebar(false)});
document.getElementById('theme-toggle').addEventListener('click',()=>{saved.theme=saved.theme==='light'?'dark':'light';persist();render()});
document.getElementById('add-course').addEventListener('click',()=>document.getElementById('course-dialog').showModal());
document.getElementById('course-form').addEventListener('submit',event=>{if(event.submitter?.value!=='save')return;const input=document.getElementById('course-name'),name=input.value.trim();if(!name){event.preventDefault();input.focus();return}saved.customCourses.push({id:'custom-'+Date.now(),name});persist();input.value='';setTimeout(()=>go('courses'),0)});
document.getElementById('edit-course-form').addEventListener('submit',event=>{if(event.submitter?.value!=='save')return;const course=customCourse(state.manageCourseId),input=document.getElementById('edit-course-name'),name=input.value.trim();if(!course||!name){event.preventDefault();input.focus();return}course.name=name;persist();setTimeout(()=>render(),0)});
document.getElementById('delete-course-form').addEventListener('submit',event=>{if(event.submitter?.value!=='delete')return;const id=state.manageCourseId;if(!customCourse(id))return;saved.customCourses=saved.customCourses.filter(c=>c.id!==id);if(state.course===id)state.course='oop';state.manageCourseId=null;persist();setTimeout(()=>go('courses'),0)});
document.addEventListener('keydown',event=>{if(state.screen!=='flash-study'||state.flashMode!=='flip'||['INPUT','TEXTAREA'].includes(document.activeElement?.tagName))return;if(event.code==='Space'){event.preventDefault();state.flipped=!state.flipped;render()}else if(event.code==='ArrowRight'){cardStep(1)}else if(event.code==='ArrowLeft'){cardStep(-1)}});
render();
